SELECT id, tenant_id, user_id, session_id, token_family_id, status, expire_at
FROM iam_refresh_token
WHERE token_hash = #{tokenHash}

mapper.update:
UPDATE iam_login_delivery
SET delivery_status = 'CONFIRMED', confirmed_at = #{now},
    version = version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND session_id = #{sessionId}
  AND delivery_status = 'PENDING'

UPDATE iam_login_session
SET status = 'REVOKED', revoked_at = #{now},
    revoke_reason = 'LOGIN_DELIVERY_UNCONFIRMED',
    session_version = session_version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND session_id = #{sessionId}
  AND status = 'ACTIVE'

UPDATE iam_refresh_token
SET status = 'REVOKED', revoked_at = #{now},
    revoke_reason = 'LOGIN_DELIVERY_UNCONFIRMED',
    version = version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND session_id = #{sessionId}
  AND status IN ('ACTIVE', 'ROTATED')

UPDATE iam_login_delivery
SET delivery_status = 'RECONCILED', reconciled_at = #{now},
    version = version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND session_id = #{sessionId}
  AND delivery_status = 'PENDING'

UPDATE iam_password_credential
SET password_phc = #{passwordPhc}, password_version = password_version + 1,
    changed_at = #{now}, version = version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND user_id = #{userId}
  AND status = 'ACTIVE' AND password_version = #{expectedPasswordVersion}

UPDATE iam_user_security_state
SET token_version = token_version + 1,
    password_version = password_version + 1,
    last_password_change_at = #{now}, version = version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND user_id = #{userId}
  AND token_version = #{expectedTokenVersion}
  AND password_version = #{expectedPasswordVersion}

UPDATE iam_login_session
SET status = 'REVOKED', revoked_at = #{now}, revoke_reason = 'PASSWORD_CHANGED',
    session_version = session_version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND user_id = #{userId} AND status = 'ACTIVE'
  AND session_id IN

      #{sessionId}

UPDATE iam_refresh_token
SET status = 'REVOKED', revoked_at = #{now}, revoke_reason = 'PASSWORD_CHANGED',
    version = version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND user_id = #{userId}
  AND status IN ('ACTIVE', 'ROTATED')
  AND session_id IN

      #{sessionId}

UPDATE iam_webauthn_challenge
SET status = 'CONSUMED'
WHERE tenant_id = #{tenantId}
  AND challenge_id = #{challengeId}
  AND status = 'PENDING'
  AND expires_at > #{now}

UPDATE iam_webauthn_credential
SET sign_count = #{signCount}, last_used_at = #{lastUsedAt}
WHERE tenant_id = #{tenantId} AND id = #{id} AND status = 'ACTIVE'

